PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS halls (id TEXT PRIMARY KEY, name TEXT NOT NULL, official_url TEXT, hours TEXT, lottery_time TEXT, lottery_place TEXT, lottery_method TEXT, parking TEXT);
CREATE TABLE IF NOT EXISTS hall_locations (hall_id TEXT PRIMARY KEY REFERENCES halls(id), address TEXT NOT NULL, lat REAL NOT NULL CHECK(lat BETWEEN -90 AND 90), lng REAL NOT NULL CHECK(lng BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS machines (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS machine_aliases (alias TEXT PRIMARY KEY, machine_id TEXT NOT NULL REFERENCES machines(id));
CREATE TABLE IF NOT EXISTS data_sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, method TEXT NOT NULL, permission TEXT NOT NULL, reliability TEXT NOT NULL, definition TEXT NOT NULL, retrieved_at TEXT NOT NULL, published_at TEXT);
CREATE TABLE IF NOT EXISTS hall_machine_installations (hall_id TEXT REFERENCES halls(id), machine_id TEXT REFERENCES machines(id), valid_from TEXT NOT NULL, valid_to TEXT, units INTEGER NOT NULL CHECK(units>0), PRIMARY KEY(hall_id,machine_id,valid_from));
CREATE TABLE IF NOT EXISTS daily_machine_results (hall_id TEXT REFERENCES halls(id), machine_id TEXT REFERENCES machines(id), date TEXT NOT NULL, total_diff INTEGER NOT NULL, units INTEGER NOT NULL CHECK(units>0), positive_units INTEGER CHECK(positive_units BETWEEN 0 AND units), games INTEGER CHECK(games>=0), source_id TEXT NOT NULL REFERENCES data_sources(id), updated_at TEXT NOT NULL, PRIMARY KEY(hall_id,machine_id,date));
CREATE INDEX IF NOT EXISTS machine_results_date ON daily_machine_results(date,hall_id,machine_id);
CREATE TABLE IF NOT EXISTS daily_hall_results (hall_id TEXT REFERENCES halls(id), date TEXT NOT NULL, total_diff INTEGER NOT NULL, units INTEGER NOT NULL, positive_units INTEGER, games INTEGER, source_id TEXT REFERENCES data_sources(id), updated_at TEXT NOT NULL, PRIMARY KEY(hall_id,date));
CREATE TABLE IF NOT EXISTS daily_unit_results (hall_id TEXT REFERENCES halls(id), machine_id TEXT REFERENCES machines(id), date TEXT NOT NULL, unit_number TEXT NOT NULL, diff INTEGER, games INTEGER, bb INTEGER, reg INTEGER, position TEXT, source_id TEXT REFERENCES data_sources(id), PRIMARY KEY(hall_id,date,unit_number));
CREATE INDEX IF NOT EXISTS unit_results_machine_date ON daily_unit_results(machine_id,date);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, hall_id TEXT REFERENCES halls(id), date TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, performer TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('announced','confirmed','cancelled')), published_at TEXT);
CREATE INDEX IF NOT EXISTS events_hall_date ON events(hall_id,date);
CREATE TABLE IF NOT EXISTS event_sources (event_id TEXT REFERENCES events(id), source_id TEXT REFERENCES data_sources(id), url TEXT, PRIMARY KEY(event_id,source_id));
CREATE TABLE IF NOT EXISTS lottery_records (id INTEGER PRIMARY KEY, hall_id TEXT REFERENCES halls(id), date TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('actual','forecast','limit','reported_average')), people INTEGER NOT NULL, source_id TEXT REFERENCES data_sources(id));
CREATE TABLE IF NOT EXISTS special_days (hall_id TEXT REFERENCES halls(id), kind TEXT NOT NULL CHECK(kind IN ('digit','day')), value INTEGER NOT NULL, source_id TEXT REFERENCES data_sources(id), PRIMARY KEY(hall_id,kind,value));
CREATE TABLE IF NOT EXISTS import_jobs (id INTEGER PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, source TEXT NOT NULL, row_count INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS data_revisions (id INTEGER PRIMARY KEY, job_id INTEGER REFERENCES import_jobs(id), entity TEXT NOT NULL, entity_key TEXT NOT NULL, before_json TEXT, after_json TEXT NOT NULL, changed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_searches (id TEXT PRIMARY KEY, owner_id TEXT, name TEXT NOT NULL, conditions_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favorites (owner_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, PRIMARY KEY(owner_id,entity_type,entity_id));
